<template>
  <div id="exam-escrito">
    <h2>Generar Nuevo Examen</h2>
    <img
        src='../assets/7.png'
        alt="Upload Exam"
        class="upload-image"
    />

    <form @submit.prevent="generateExam">
      <!-- Subir Logo -->
      <div>
        <label class="upload-label" for="logo">
          <i class="fas fa-upload"></i> Subir Insignia (Logo)
        </label>
        <input type="file" id="logo" @change="handleLogoUpload" />
      </div>

      <!-- Vista previa -->
      <div v-if="examData.logo" class="preview">
        <img :src="examData.logo" alt="Vista previa del logo" />
      </div>


      <!-- Información del Examen -->
      <div>
        <label for="institucion">Nombre de la Institución:</label>
        <input v-model="examData.institucion" type="text" placeholder="Nombre de la institución" />
      </div>
      <div>
        <label for="direccion">Dirección del Colegio:</label>
        <input v-model="examData.direccion" type="text" placeholder="Dirección" />
      </div>
      <div>
        <label for="titulo">Título del Examen:</label>
        <input v-model="examData.titulo" type="text" placeholder="Título del examen" />
      </div>


<!-- Preguntas -->
<div v-for="(question, index) in examData.preguntas" :key="index" >
  <div style="display: flex; justify-content: space-between; align-items: center;">
    <label :for="'pregunta-' + index">Pregunta {{ index + 1 }}:</label>
    <!-- Eliminar pregunta -->
    <button
      type="button"
      @click="examData.preguntas.splice(index, 1)"
      style="background-color: #dc3545; color: white; border: none; border-radius: 5px; padding: 6px 10px; cursor: pointer;"
      title="Eliminar esta pregunta"
    >
      <i class="fas fa-trash"></i>
    </button>
  </div>

  <input v-model="question.texto" type="text" placeholder="Escribe la pregunta aquí" style="width: 100%; margin-top: 5px;" />

  <!-- Tipo de Pregunta -->
  <div style="margin-top: 10px;">
    <label>Tipo de Pregunta:</label>
    <select v-model="question.tipo">
      <option value="rellenar">Rellenar</option>
      <option value="marcar">Marcar (Opción múltiple)</option>
    </select>
  </div>

        <!-- Opciones para Marcar -->
        <div v-if="question.tipo === 'marcar'" style="margin-top: 10px;">
          <label>Opciones:</label>
          <div
            v-for="(option, $index) in question.opciones"
            :key="$index"
            style="display: flex; align-items: center; gap: 10px; margin-bottom: 8px;"
          >
            <input
              v-model="question.opciones[$index]"
              type="text"
              placeholder="Opción"
              style="flex: 1;"
            />
            <!-- Eliminar opción -->
            <button
              type="button"
              @click="question.opciones.splice($index, 1)"
              style="background-color: #dc3545; color: white; border: none; border-radius: 5px; width: 35px; height: 35px; display: flex; align-items: center; justify-content: center; cursor: pointer; margin-top: -13px;"
              title="Eliminar esta opción"
            >
              <i class="fas fa-trash"></i>
            </button>
          </div>
          <!-- Agregar opción -->
          <button type="button" @click="question.opciones.push('')">Agregar Opción</button>
        </div>
      </div>

      <button type="button" @click="addQuestion">Agregar Pregunta</button>
      <button type="submit">Generar Examen en PDF</button>
    </form>
  </div>
</template>

<script>
import jsPDF from 'jspdf';

export default {
  name: 'ExamEscrito',
  data() {
    return {
      examData: {
        logo: null,
        institucion: '',
        direccion: '',
        titulo: '',
        preguntas: [
          { texto: '', tipo: 'rellenar', opciones: [], userAnswers: [] },
        ],
      }
    };
  },
  methods: {
    handleLogoUpload(event) {
      const file = event.target.files[0];
      if (file && file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = () => {
          this.examData.logo = reader.result; 
        };
        reader.readAsDataURL(file);
      } else {
        alert('Por favor, sube una imagen válida.');
      }
    },

    addQuestion() {
      this.examData.preguntas.push({ texto: '', tipo: 'rellenar', opciones: [], userAnswers: [] });
    },

    addOption(questionIndex) {
      this.examData.preguntas[questionIndex].opciones.push('');
    },

    removeOption(questionIndex, optionIndex) {
      this.examData.preguntas[questionIndex].opciones.splice(optionIndex, 1);
    },

    generateExam() {
      const doc = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      // Dibujar un marco
      doc.setLineWidth(0.5);
      doc.rect(5, 5, 200, 287);

      // Insignia predeterminada (simulada)
      const insigniaPredeterminada = 'data:image/png;base64,';

      if (insigniaPredeterminada) {
        doc.addImage(insigniaPredeterminada, 'PNG', 165, 10, 40, 30);
      }

      // Logo
      if (this.examData.logo) {
        doc.addImage(this.examData.logo, 'PNG', 15, 15, 20, 20);
      }

      doc.setFontSize(12);
      doc.setFont('helvetica', 'bold');
      doc.text(this.examData.institucion.toUpperCase(), 105, 20, { align: 'center' });

      doc.setFontSize(12);
      doc.setFont('helvetica', 'normal');
      doc.text('Dirección: ' + this.examData.direccion, 105, 30, { align: 'center' });

      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.text(this.examData.titulo.toUpperCase(), 105, 40, { align: 'center' });

      doc.setLineWidth(0.5);
      doc.line(10, 50, 200, 50);

      doc.setFontSize(12);
      doc.setFont('helvetica', 'normal');
      doc.text('Nombre completo: ____________________________________________', 15, 60);
      doc.text('Grado: __________ ', 15, 70);
      doc.text('Sección: __________ ', 15, 80);

      doc.line(10, 85, 200, 85);

      let yOffset = 95;

      this.examData.preguntas.forEach((question, index) => {
        doc.setFontSize(12);
        doc.setFont('helvetica', 'bold');
        doc.text(`Pregunta ${index + 1}:`, 15, yOffset);
        yOffset += 7;

        // --- Ajustar texto de la pregunta si es largo ---
        doc.setFont('helvetica', 'normal');
        let maxWidth = 170; // ancho máximo del texto en la página
        let splitText = doc.splitTextToSize(question.texto, maxWidth);

        doc.text(splitText, 20, yOffset); // imprime el texto en varias líneas
        yOffset += splitText.length * 7; // mover yOffset según las líneas

        if (question.tipo === 'marcar') {
          let xOffset = 20;
          question.opciones.forEach((option) => {
            doc.rect(xOffset, yOffset - 4, 5, 5);
            doc.text(option, xOffset + 7, yOffset);
            xOffset += option.length * 3.5 + 20;
          });
          yOffset += 12;
        }

        yOffset += 8;
        if (yOffset > 270) {
          doc.addPage();
          doc.rect(5, 5, 200, 287);
          yOffset = 20;
        }
      });

      doc.setFontSize(10);
      doc.setTextColor(150);
      doc.text('Generado por EduTK', 105, 290, { align: 'center' });

      //doc.save('examen.pdf');
      // Crear el PDF
      const pdfOutput = doc.output('blob');

      // Crear un enlace de descarga
      const link = document.createElement('a');
      link.href = URL.createObjectURL(pdfOutput);
      link.download = `examen.pdf`;

      // Agregar el enlace al DOM, simular el clic y luego eliminarlo
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    },
  }
};
</script>

